  function lookupNearestLowerTableAmount(table, earnings, claimTaxFreeThreshold){
    const amount = Math.max(0, Math.floor(Number(earnings||0)));
    let lo = 0, hi = table.length - 1, found = -1;
    while(lo <= hi){
      const mid = Math.floor((lo+hi)/2);
      if(table[mid][0] <= amount){ found = mid; lo = mid + 1; }
      else hi = mid - 1;
    }
    if(found < 0) return 0;
    return Number(table[found][claimTaxFreeThreshold ? 1 : 2] || 0);
  }
  function lookupFortnightlyPAYG(earnings, claimTaxFreeThreshold=true){
    const amount = Math.max(0, Number(earnings||0));
    if(amount > 6800){
      if(claimTaxFreeThreshold){
        if(amount < 7306) return Math.round(1936 + (amount - 6800) * 0.39);
        return Math.round(2134 + (amount - 7305) * 0.47);
      }
      return Math.round(2222 + (amount - 6800) * 0.47);
    }
    return lookupNearestLowerTableAmount(FORTNIGHTLY_PAYG_TABLE, amount, claimTaxFreeThreshold);
  }
